  { id: "q19", q: "បំពេញប្រយោគដោយប្រើសព្វនាមកម្មសិទ្ធិ៖ 'The students are reading _______ storybooks quietly.'", options: ["they", "them", "their", "theirs"], correct: 2, exp: "មុននាម 'storybooks' ត្រូវប្រើគុណនាមកម្មសិទ្ធិ (Possessive Adjective) របស់ They គឺ 'their'។" },
  { id: "q20", q: "តើពាក្យ 'Lifelong learner' មានន័យថាដូចម្តេច?", options: ["អ្នកសិក្សាពេញមួយជីវិត", "សិស្សរៀនថ្នាក់ទី១", "គ្រូបង្រៀនចូលនិវត្តន៍", "ការប្រឡងឆមាស"], correct: 0, exp: "Lifelong learner មានន័យថា អ្នកសិក្សាពេញមួយជីវិត ដែលតែងតែអភិវឌ្ឍចំណេះដឹងឥតឈប់ឈរ។" }
